entries.syntax_block:
Reader = New TextReader(path, TextEncoding.UTF8);

Line = Reader.ReadLine();
while (Line <> Undefined) {        // Undefined, not "": an empty line is a line
    Line = Reader.ReadLine();
}
Reader.Close();

entries.syntax_block_ves:
Reader = New TextReader(path, TextEncoding.UTF8);

Line = Reader.ReadLine();
While Line <> Undefined Do        // Undefined, not "": an empty line is a line
    Line = Reader.ReadLine();
EndDo;
Reader.Close();

entries.example:
Reader = New TextReader("C:\in\sales.csv", TextEncoding.UTF8);
Line = Reader.ReadLine();
while (Line <> Undefined) {              // Undefined, not "": an empty line is a line
    if (Line <> "") {
        Cut = Find(Line, ";");
        Code = Left(Line, Cut - 1);      // the first field
    }
    Line = Reader.ReadLine();
}
Reader.Close();

Reader = New TextReader(first);
Message(Reader.ReadLine());
Reader.Open(second);          // the first file is let go; the reader stands at line 1 of the second
Message(Reader.ReadLine());
Reader.Close();

Line = Reader.ReadLine();
while (Line <> Undefined) {       // not while (Line <> "")
    Message(Line);
    Line = Reader.ReadLine();
}

Header = Reader.ReadLine();       // the first line on its own
Body = Reader.Read();             // everything after it, line breaks and all
Reader.Close();

Reader = New TextReader(path);
for (n = 1 To Reader.LineCount()) {
    Message(Reader.GetLine(n));
}
Reader.Close();

Reader = New TextReader(path);
Message(Reader.GetLine(1));                    // the header line
Message(Reader.GetLine(Reader.LineCount()));   // the last one
Message(Reader.ReadLine());                    // still line 1: GetLine did not move it
Reader.Close();

entries.syntax_block:
Writer = New TextWriter(path, TextEncoding.UTF8);
Writer = New TextWriter(path, TextEncoding.UTF8, True);   // append instead of replace

Writer.WriteLine("code;name;qty");
Writer.Write("00001;Paper;12");
Writer.Close();                                           // here, and only here, a failure is told

entries.example:
Writer = New TextWriter(GetTempDir() + "sales.csv", TextEncoding.UTF8);
Writer.WriteLine("code;name;qty");
Writer.WriteLine("00001;Paper;12");
Writer.Close();                      // the export is whole only once this returned

Writer = New TextWriter(first);
Writer.WriteLine("one");
Writer.Open(second);          // the first file is CLOSED here - and a close that failed is told here
Writer.WriteLine("two");
Writer.Close();

Writer.Write("00001;");
Writer.Write("Paper;");
Writer.WriteLine("12");        // the break that ends the row

try {
    Writer.Close();
} except {
    Message("the export did not reach the disk: " + ErrorDescription());
}

